  if(SKIP.indexOf(v)>=0)return null;var r=base(v);if(!r)return null;
  if(refl){r.forms=r.forms.map(function(x,i){return PRON[i]+' '+x;});r.why+=' · reflexiv: me, te, se, nos, os, se';}
